def validate_kyc(name, id_type, id_number, sanctions_list):
    valid_ids = ['passport', 'driver_license', 'national_id']
    if id_type not in valid_ids:
        return {'approved': False, 'reason': f'Invalid ID type: {id_type}'}
    if name.lower() in (s.lower() for s in sanctions_list):
        return {'approved': False, 'reason': 'Name matched sanctions list'}
    return {'approved': True, 'reason': 'KYC passed'}

def screen_transaction(sender_name, recipient_country, sanctions_list):
    sanctioned_countries = {s['country'] for s in sanctions_list}
    if recipient_country in sanctioned_countries:
        return {'flagged': True, 'reason': f'Sanctioned country: {recipient_country}'}
    for entry in sanctions_list:
        if sender_name.lower() in entry.get('name', '').lower():
            return {'flagged': True, 'reason': f'Name matched: {entry["name"]}'}
    return {'flagged': False, 'reason': 'Cleared'}

class TransactionMonitor:
    def evaluate(self, tx, history):
        reasons = []
        amounts = [h['amount'] for h in history]
        avg = sum(amounts) / len(amounts) if amounts else 0
        if tx['amount'] > 10 * avg:
            reasons.append(f'Amount {tx["amount"]} > 10x avg {avg:.0f}')
        if history and tx.get('country') and tx['country'] != history[-1].get('country'):
            reasons.append(f'Country changed to {tx["country"]}')
        if tx.get('amount', 0) > 10000 and tx.get('type') == 'wire':
            reasons.append('High-value wire transfer')
        return {'alert': len(reasons) > 0, 'reasons': reasons}

def find_ubo(ownership_chain):
    for entry in ownership_chain:
        if entry.get('type') == 'individual':
            return entry['owner']
    return 'UBO not found — chain incomplete'

def plot_vol_surface(strikes, expiries, vols):
    print('Vol Surface:')
    print('       ', ' '.join(f'{e:>5}d' for e in expiries))
    for i, strike in enumerate(strikes):
        row = f'{strike:>5} '
        for j in range(len(expiries)):
            v = vols[i][j]
            c = 'H' if v > 0.4 else 'M' if v > 0.25 else 'L'
            row += f'  {c}:{v:.2f}'
        print(row)

import math
def factor_correlation(factor_a, factor_b, returns):
    def corr(x, y):
        n = len(x)
        mx, my = sum(x)/n, sum(y)/n
        num = sum((xi-mx)*(yi-my) for xi, yi in zip(x, y))
        den = math.sqrt(sum((xi-mx)**2 for xi in x)) * math.sqrt(sum((yi-my)**2 for yi in y))
        return num / den if den else 0
    return {
        'factor_a_corr': round(corr(factor_a, returns), 3),
        'factor_b_corr': round(corr(factor_b, returns), 3),
        'factor_a_vs_b': round(corr(factor_a, factor_b), 3)
    }

import random
def simulate_behavioral_portfolio(initial=10000, days=252, panic_threshold=0.3, recovery_threshold=0.7):
    price = 100
    prices = [price]
    for d in range(days):
        ret = random.gauss(0, 0.015)
        if d == 30:
            ret = -panic_threshold
        price *= (1 + ret)
        prices.append(price)
    buy_hold = [initial * p / prices[0] for p in prices]
    panic = [initial]
    for d, p in enumerate(prices):
        if d == 31:
            panic.append(prices[30] * 0.95)  # sold at bottom
        elif d > 31:
            panic.append(panic[-1])
        else:
            panic.append(initial * p / prices[0])
    return {'buy_hold': buy_hold, 'panic_seller': panic}

def etl_pipeline(extract_fn, transform_fn, load_fn):
    try:
        data = extract_fn()
    except Exception as e:
        return {'success': False, 'step': 'extract', 'error': str(e)}
    try:
        transformed = transform_fn(data)
    except Exception as e:
        return {'success': False, 'step': 'transform', 'error': str(e)}
    try:
        result = load_fn(transformed)
    except Exception as e:
        return {'success': False, 'step': 'load', 'error': str(e)}
    return {'success': True, 'rows_loaded': len(transformed)}

import statistics
class StreamProcessor:
    def __init__(self, window_size=300):
        self.window = []
        self.max_size = window_size
    def process(self, event):
        self.window.append(event['value'])
        if len(self.window) > self.max_size:
            self.window.pop(0)
        avg = statistics.mean(self.window)
        if len(self.window) > 1:
            std = statistics.stdev(self.window)
            alert = abs(event['value'] - avg) > 3 * std
        else:
            alert = False
        return {'avg': round(avg, 2), 'event_count': len(self.window), 'alert': alert}

class InMemoryKafka:
    def __init__(self):
        self._topics = {}
    def create_topic(self, name):
        if name not in self._topics:
            self._topics[name] = []
    def produce(self, topic, message):
        self._topics.setdefault(topic, []).append(message)
        return len(self._topics[topic]) - 1
    def consume(self, topic, offset=-1):
        msgs = self._topics.get(topic, [])
        if offset < 0:
            return msgs
        return msgs[offset:]
